pub fn fnv1a64(bytes:&[u8])->u64{let mut h=0xcbf29ce484222325u64;for b in bytes{h^=*b as u64;h=h.wrapping_mul(0x100000001b3);}h}
pub fn digest(parts:&[&str])->String{let mut buf=Vec::new();for p in parts{buf.extend_from_slice(&(p.len() as u64).to_be_bytes());buf.extend_from_slice(p.as_bytes());}format!("{:016x}",fnv1a64(&buf))}
pub fn canonical_json<T:serde::Serialize>(v:&T)->std::result::Result<String,serde_json::Error>{let value=serde_json::to_value(v)?;fn norm(v:serde_json::Value)->serde_json::Value{match v{serde_json::Value::Object(m)=>{let mut ks:Vec<_>=m.into_iter().collect();ks.sort_by(|a,b|a.0.cmp(&b.0));serde_json::Value::Object(ks.into_iter().map(|(k,v)|(k,norm(v))).collect())},serde_json::Value::Array(a)=>serde_json::Value::Array(a.into_iter().map(norm).collect()),x=>x}}serde_json::to_string(&norm(value))}